import * as BunRuntime from "@effect/platform-bun/BunRuntime";
import * as BunServices from "@effect/platform-bun/BunServices";
import { Array, Console, Effect, Match, Option, Schema, Stream } from "effect";
import * as FileSystem from "effect/FileSystem";
import { pipe } from "effect/Function";
import * as Path from "effect/Path";
import { ChildProcess, ChildProcessSpawner } from "effect/unstable/process";

import {
  decodeReadableRepositoryText,
  inspectRepositoryText,
  makeRepositoryPathReport,
  renderRepositoryPathReport,
} from "./policy.js";
import {
  RepositoryFileReadError,
  RepositoryInventoryError,
  RepositoryPolicyViolationError,
  RepositoryRelativeFile,
} from "./schemas.js";

const repositoryRootUrl = new URL("../..", import.meta.url);
const TrackedFileInventory = Schema.Array(RepositoryRelativeFile);

export const checkRepositoryPaths = (repositoryRoot: string) =>
  Effect.gen(function* checkTrackedRepositoryText() {
    const childProcesses = yield* ChildProcessSpawner.ChildProcessSpawner;
    const fileSystem = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;

    const inventory = yield* Effect.gen(function* listTrackedFiles() {
      const handle = yield* childProcesses.spawn(
        ChildProcess.make("git", ["ls-files", "-z"], {
          cwd: repositoryRoot,
          extendEnv: true,
          forceKillAfter: "2 seconds",
          stderr: "pipe",
          stdin: "ignore",
          stdout: "pipe",
        })
      );
      const [stdout, [exitCode]] = yield* Effect.all(
        [
          Stream.runCollect(handle.stdout),
          Effect.zip(handle.exitCode, Stream.runDrain(handle.stderr), {
            concurrent: true,
          }),
        ],
        { concurrency: "unbounded" }
      );

      yield* Match.value(Number(exitCode)).pipe(
        Match.when(0, () => Effect.void),
        Match.orElse((code) =>
          Effect.fail(
            new RepositoryInventoryError({
              exitCode: code,
              operation: "list-tracked-files",
            })
          )
        )
      );

      const bytes = Uint8Array.from(Array.flatMap(stdout, Array.fromIterable));
      const decoded = yield* Effect.try({
        catch: () =>
          new RepositoryInventoryError({
            operation: "decode-tracked-files",
          }),
        try: () => new TextDecoder("utf-8", { fatal: true }).decode(bytes),
      });

      return yield* pipe(
        decoded.split("\0"),
        Array.filter((file) => file.length > 0),
        Schema.decodeUnknownEffect(TrackedFileInventory),
        Effect.mapError(
          () =>
            new RepositoryInventoryError({
              operation: "decode-tracked-files",
            })
        )
      );
    }).pipe(
      Effect.scoped,
      Effect.catchTag("PlatformError", () =>
        Effect.fail(
          new RepositoryInventoryError({
            operation: "list-tracked-files",
          })
        )
      )
    );

    const inspected = yield* Effect.forEach(
      inventory,
      (file) => {
        const filePath = path.join(repositoryRoot, file);

        return fileSystem.readLink(filePath).pipe(
          Effect.map((target) => new TextEncoder().encode(target)),
          Effect.catchTag("PlatformError", () => fileSystem.readFile(filePath)),
          Effect.mapError(() => new RepositoryFileReadError({ file })),
          Effect.map((bytes) =>
            decodeReadableRepositoryText(bytes).pipe(
              Option.match({
                onNone: () => ({ binary: true, findings: [] }),
                onSome: (text) => ({
                  binary: false,
                  findings: inspectRepositoryText(file, text),
                }),
              })
            )
          )
        );
      },
      { concurrency: 16 }
    );
    const binaryFiles = Array.filter(inspected, (file) => file.binary).length;

    return makeRepositoryPathReport({
      binaryFiles,
      findings: Array.flatMap(inspected, (file) => file.findings),
      textFiles: inspected.length - binaryFiles,
      trackedFiles: inventory.length,
    });
  });

const program = Effect.gen(function* repositoryPathMain() {
  const path = yield* Path.Path;
  const repositoryRoot = yield* path.fromFileUrl(repositoryRootUrl).pipe(
    Effect.mapError(
      () =>
        new RepositoryInventoryError({
          operation: "resolve-repository-root",
        })
    )
  );

  return yield* checkRepositoryPaths(repositoryRoot);
}).pipe(
  Effect.tap((report) => Console.info(renderRepositoryPathReport(report))),
  Effect.tap((report) =>
    Match.value(report.findings.length).pipe(
      Match.when(0, () => Effect.void),
      Match.orElse(() =>
        Effect.fail(new RepositoryPolicyViolationError({ report }))
      )
    )
  ),
  Effect.tapErrorTag("RepositoryInventoryError", (error) =>
    Console.error(
      `Repository path check failed during ${error.operation}${Option.fromNullishOr(
        error.exitCode
      ).pipe(
        Option.match({
          onNone: () => "",
          onSome: (exitCode) => ` (exit ${exitCode})`,
        })
      )}.`
    )
  ),
  Effect.tapErrorTag("RepositoryFileReadError", (error) =>
    Console.error(`Repository path check could not read ${error.file}.`)
  ),
  Effect.tapErrorTag("RepositoryPolicyViolationError", () => Effect.void),
  Effect.provide(BunServices.layer)
);

Match.value(import.meta.main).pipe(
  Match.when(true, () => BunRuntime.runMain(program)),
  Match.orElse(() => false)
);
import { Array, Match, Option, Order, Result } from "effect";
import { pipe } from "effect/Function";

import { RepositoryPathFinding, RepositoryPathReport } from "./schemas.js";
import type {
  RepositoryPathCategory,
  RepositoryRelativeFile,
} from "./schemas.js";

const homeDirectoryName = ["Us", "ers"].join("");
const checkoutDirectoryName = ["Pro", "jects"].join("");
const httpsReference = new RegExp("https://[^\\s)\\]}>]+", "gu");
const homeFileUrl = new RegExp(
  `file:///(?:${homeDirectoryName}|home)/[^/\\s]+(?:/|$)`,
  "u"
);
const windowsHomePath = new RegExp(
  `[A-Za-z]:[\\\\/]${homeDirectoryName}[\\\\/][^\\\\/\\s]+(?:[\\\\/]|$)`,
  "u"
);
const tildeCheckoutPath = new RegExp(
  `~[\\\\/]${checkoutDirectoryName}(?:[\\\\/]|$)`,
  "u"
);
const posixHomePath = new RegExp(
  `/(?:${homeDirectoryName}|home)/[^/\\s]+(?:/|$)`,
  "u"
);
const checkoutDirectoryPath = new RegExp(
  `(?:^|[^A-Za-z0-9_.~-])${checkoutDirectoryName}/[A-Za-z0-9._-]+`,
  "u"
);

const categoryForLine = (
  line: string
): Option.Option<RepositoryPathCategory> => {
  const candidate = line.replace(httpsReference, "");

  return Match.value(candidate).pipe(
    Match.when(
      (value) => homeFileUrl.test(value),
      () => "home-file-url" as const
    ),
    Match.when(
      (value) => windowsHomePath.test(value),
      () => "windows-home-path" as const
    ),
    Match.when(
      (value) => tildeCheckoutPath.test(value),
      () => "tilde-checkout-path" as const
    ),
    Match.when(
      (value) => posixHomePath.test(value),
      () => "posix-home-path" as const
    ),
    Match.when(
      (value) => checkoutDirectoryPath.test(value),
      () => "checkout-directory-path" as const
    ),
    Match.option
  );
};

export const inspectRepositoryText = (
  file: RepositoryRelativeFile,
  text: string
): readonly RepositoryPathFinding[] =>
  pipe(
    text.split(/\r?\n/u),
    Array.map((line, index) =>
      Option.map(
        categoryForLine(line),
        (category) =>
          new RepositoryPathFinding({
            category,
            file,
            line: index + 1,
          })
      )
    ),
    Array.getSomes
  );

export const decodeReadableRepositoryText = (
  bytes: Uint8Array
): Option.Option<string> =>
  bytes.includes(0)
    ? Option.none()
    : Result.try(() =>
        new TextDecoder("utf-8", { fatal: true }).decode(bytes)
      ).pipe(
        Result.match({
          onFailure: Option.none,
          onSuccess: Option.some,
        })
      );

const findingOrder = Order.combineAll<RepositoryPathFinding>([
  Order.mapInput(Order.String, (finding) => finding.file),
  Order.mapInput(Order.Number, (finding) => finding.line),
  Order.mapInput(Order.String, (finding) => finding.category),
]);

const sortRepositoryPathFindings = (
  findings: Iterable<RepositoryPathFinding>
): readonly RepositoryPathFinding[] => Array.sort(findings, findingOrder);

export const renderRepositoryPathReport = (
  report: RepositoryPathReport
): string =>
  Match.value(report.findings.length).pipe(
    Match.when(
      0,
      () =>
        `Repository path check passed: ${report.textFiles} text and ${report.binaryFiles} binary files from ${report.trackedFiles} tracked files.`
    ),
    Match.orElse(() =>
      [
        `Repository path check failed with ${report.findings.length} finding(s):`,
        ...Array.map(
          report.findings,
          (finding) => `${finding.file}:${finding.line} [${finding.category}]`
        ),
      ].join("\n")
    )
  );

export const makeRepositoryPathReport = (options: {
  readonly binaryFiles: number;
  readonly findings: Iterable<RepositoryPathFinding>;
  readonly textFiles: number;
  readonly trackedFiles: number;
}): RepositoryPathReport =>
  new RepositoryPathReport({
    binaryFiles: options.binaryFiles,
    findings: sortRepositoryPathFindings(options.findings),
    textFiles: options.textFiles,
    trackedFiles: options.trackedFiles,
  });
import { Array, Option, Schema } from "effect";

export const RepositoryPathCategory = Schema.Literals([
  "checkout-directory-path",
  "home-file-url",
  "posix-home-path",
  "tilde-checkout-path",
  "windows-home-path",
]);
export type RepositoryPathCategory = typeof RepositoryPathCategory.Type;

export const RepositoryRelativeFile = Schema.NonEmptyString.pipe(
  Schema.check(
    Schema.isPattern(/^(?!\/)(?!.*(?:^|\/)\.\.(?:\/|$)).+$/u),
    Schema.makeFilter((file) =>
      Array.every(Array.fromIterable(file), (character) =>
        Option.fromNullishOr(character.codePointAt(0)).pipe(
          Option.exists((code) => code >= 32 && code !== 127)
        )
      )
        ? undefined
        : "Repository-relative paths must not contain control characters."
    )
  ),
  Schema.brand("taxkit/RepositoryRelativeFile")
);
export type RepositoryRelativeFile = typeof RepositoryRelativeFile.Type;

const RepositoryPathLine = Schema.Int.check(Schema.isGreaterThan(0));

export class RepositoryPathFinding extends Schema.TaggedClass<RepositoryPathFinding>()(
  "RepositoryPathFinding",
  {
    category: RepositoryPathCategory,
    file: RepositoryRelativeFile,
    line: RepositoryPathLine,
  }
) {}

export class RepositoryPathReport extends Schema.TaggedClass<RepositoryPathReport>()(
  "RepositoryPathReport",
  {
    binaryFiles: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
    findings: Schema.Array(RepositoryPathFinding),
    textFiles: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
    trackedFiles: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  }
) {}

export class RepositoryPolicyViolationError extends Schema.TaggedErrorClass<RepositoryPolicyViolationError>()(
  "RepositoryPolicyViolationError",
  {
    report: RepositoryPathReport,
  }
) {}

const RepositoryInventoryOperation = Schema.Literals([
  "decode-tracked-files",
  "list-tracked-files",
  "resolve-repository-root",
]);

export class RepositoryInventoryError extends Schema.TaggedErrorClass<RepositoryInventoryError>()(
  "RepositoryInventoryError",
  {
    exitCode: Schema.optional(Schema.Int),
    operation: RepositoryInventoryOperation,
  }
) {}

export class RepositoryFileReadError extends Schema.TaggedErrorClass<RepositoryFileReadError>()(
  "RepositoryFileReadError",
  {
    file: RepositoryRelativeFile,
  }
) {}

